from collections import deque

def find_all_pathways(start_color, end_color, start_bboxes, end_cells_set, grid, bg_val):
    """Find all 8-components of start_color that can reach any end_color cell through background only"""
    pathways = {}

    # For each 8-component, try BFS from its cells through background to reach any end_cell
    for comp_idx in range(len(start_bboxes)):
        comp_changed = False

        for r, c in start_bboxes[comp_idx]:
            # BFS from this cell through background until we hit an end cell
            queue = deque([(r, c)])
            seen = {(r, c)}

            while queue:
                cr, cc = queue.popleft()

                # Check neighbors
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        val = grid[nr][nc]
                        if val == end_color:
                            pathways[comp_idx] = True
                            comp_changed = True
                            break
                        elif val != bg_val and val != start_color and val != end_color:
                            continue  # Blocked by other color

                        if (nr, nc) not in seen:
                            seen.add((nr, nc))
                            queue.append((nr, nc))
                if comp_changed:
                    break

        if not comp_changed:
            pathways[comp_idx] = False

    return pathways

